declare global {
  interface Window { L: typeof import('leaflet'); }
}

function loadScript(src: string): Promise<void> {
  return new Promise((resolve, reject) => {
    if (document.querySelector(`script[src="${src}"]`)) { resolve(); return; }
    const s = document.createElement('script');
    s.src = src;
    s.onload = () => resolve();
    s.onerror = reject;
    document.head.appendChild(s);
  });
}

function loadStyle(href: string): void {
  if (document.querySelector(`link[href="${href}"]`)) return;
  const l = document.createElement('link');
  l.rel = 'stylesheet';
  l.href = href;
  document.head.appendChild(l);
}


// Coordinate label for right-click weather
function coordLabel(lat: number, lng: number): string {
  const latS = `${Math.abs(lat).toFixed(3)}°${lat >= 0 ? 'N' : 'S'}`;
  const lngS = `${Math.abs(lng).toFixed(3)}°${lng >= 0 ? 'E' : 'W'}`;
  return `${latS}, ${lngS}`;
}

// ─── App ──────────────────────────────────────────────────────────────────────

interface WeatherPlace {
  id:   string;
  name: string;
  lat:  number;
  lng:  number;
}

interface AppProps {
  topBarRight?: React.ReactNode;
}

export default function App({ topBarRight }: AppProps) {
  const mapElRef      = useRef<HTMLDivElement>(null);
  const mapRef        = useRef<import('leaflet').Map | null>(null);
  const markerMapRef  = useRef<Map<string, import('leaflet').Marker>>(new Map());
  const tileLayerRef  = useRef<import('leaflet').TileLayer | null>(null);

  const [coords,          setCoords]          = useState({ lat: 0, lng: 0, zoom: 2 });
  const [ready,           setReady]           = useState(false);
  const [activePlace,     setActivePlace]     = useState<string | null>(null);
  const [weatherPlace,    setWeatherPlace]    = useState<WeatherPlace | null>(null);
  const { recent, addRecent } = usePlaceRecents('atlantis:earth:recent');
  const [now,             setNow]             = useState(() => new Date());
  const [mapInstance,     setMapInstance]     = useState<import('leaflet').Map | null>(null);
  const [showRcHint,      setShowRcHint]      = useState(false);
  const [showSaveDialog,  setShowSaveDialog]  = useState(false);
  const [docNote,         setDocNote]         = useState<string | null>(null);

  // Non-plugin toggles
  const [showFlags,   setShowFlags]   = useState(true);
  const [satellite,   setSatellite]   = useState(false);

  // Plugin layer enabled state — keyed by plugin id
  const [enabledLayers, setEnabledLayers] = useState<Set<string>>(defaultEnabledSet);

  const toggleLayer = useCallback((id: string) => {
    setEnabledLayers((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  }, []);

  // Clock
  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(id);
  }, []);

  // Seed changelog on first run

  // ── Document helpers ──────────────────────────────────────────────────────
  const [currentDoc, setCurrentDoc] = useState<{ id: string; name: string } | null>(null);

  const handleSave = useCallback(async (name: string) => {
    const doc: EarthDoc = {
      version: 2,
      enabled: Array.from(enabledLayers),
      satellite,
      showFlags,
    };
    await saveDoc(EARTH_APP_ID, name, JSON.stringify(doc));
    setShowSaveDialog(false);
    setCurrentDoc(null);
  }, [enabledLayers, satellite, showFlags]);

  const handleUpdate = useCallback(async () => {
    if (!currentDoc) return;
    const doc: EarthDoc = {
      version: 2,
      enabled: Array.from(enabledLayers),
      satellite,
      showFlags,
    };
    await updateDoc(currentDoc.id, currentDoc.name, JSON.stringify(doc));
    setShowSaveDialog(false);
  }, [currentDoc, enabledLayers, satellite, showFlags]);

  const handleLoad = useCallback((content: string, docId?: string, docName?: string) => {
    setCurrentDoc(docId && docName ? { id: docId, name: docName } : null);
    try {
      const raw = JSON.parse(content) as Record<string, unknown>;
      if (raw['version'] === 2) {
        const doc = raw as unknown as EarthDoc;
        setSatellite(doc.satellite);
        setShowFlags(doc.showFlags);
        setEnabledLayers(new Set(doc.enabled));
        if (doc.note) setDocNote(doc.note);
      } else if (raw['version'] === 1) {
        // Migrate v1 → v2
        const l = raw['layers'] as Record<string, boolean>;
        setSatellite(Boolean(l['satellite']));
        setShowFlags(Boolean(l['showFlags']));
        const enabled = new Set<string>();
        for (const id of ['night','aurora','iss','quakes','fires','radar','flights','measure']) {
          if (l[id]) enabled.add(id);
        }
        setEnabledLayers(enabled);
        if (raw['note']) setDocNote(raw['note'] as string);
      }
    } catch {
      // malformed doc — ignore
    }
  }, []);

  // ── Select a named place ──────────────────────────────────────────────────
  const handlePlaceSelect = useCallback((id: string) => {
    const place = ALL_PLACES.find((p) => p.id === id);
    if (place && mapRef.current) {
      mapRef.current.flyTo([place.lat, place.lng], place.zoom, { duration: 1.2 });
      setActivePlace(id);
      setWeatherPlace({ id: place.id, name: `${place.flag} ${place.name}`, lat: place.lat, lng: place.lng });
      addRecent(id);
    }
  }, [addRecent]);

  // ── Deep-link: honour ?placeId=… or ?lat=&lon=[&zoom=] from navigateTo() ──
  const navParams = useNavParams();
  const appliedDeepLinkRef = useRef<string | null>(null);
  useEffect(() => {
    if (!mapInstance) return;
    const { placeId, lat, lon, zoom } = navParams;

    if (placeId) {
      if (appliedDeepLinkRef.current === `place:${placeId}`) return;
      appliedDeepLinkRef.current = `place:${placeId}`;
      handlePlaceSelect(placeId);
      return;
    }

    const latN = parseFloat(lat ?? '');
    const lonN = parseFloat(lon ?? '');
    if (Number.isFinite(latN) && Number.isFinite(lonN)) {
      const zoomN = parseFloat(zoom ?? '');
      const targetZoom = Number.isFinite(zoomN) ? zoomN : 6;
      const sig = `coord:${latN.toFixed(4)},${lonN.toFixed(4)},${targetZoom}`;
      if (appliedDeepLinkRef.current === sig) return;
      appliedDeepLinkRef.current = sig;
      mapRef.current?.flyTo([latN, lonN], targetZoom, { duration: 1.2 });
      setActivePlace(null);
      setWeatherPlace({ id: sig, name: `${latN.toFixed(2)}°, ${lonN.toFixed(2)}°`, lat: latN, lng: lonN });
    }
  }, [mapInstance, navParams.placeId, navParams.lat, navParams.lon, navParams.zoom, handlePlaceSelect]);

  function handleNavSelect(entry: NavEntry) {
    if (entry.id.startsWith('country-') || entry.id === '__recent__') return;
    handlePlaceSelect(entry.id);
  }

  const handleReset = () => {
    mapRef.current?.flyTo([20, 0], 2, { duration: 1.2 });
    setActivePlace(null);
    setWeatherPlace(null);
  };

  const handleWeatherClose = () => {
    setActivePlace(null);
    setWeatherPlace(null);
  };

  // ── Satellite tile switching ──────────────────────────────────────────────
  useEffect(() => {
    if (!tileLayerRef.current) return;
    tileLayerRef.current.setUrl(satellite ? SATELLITE_URL : OSM_URL);
  }, [satellite]);

  // ── Active marker highlight ───────────────────────────────────────────────
  useEffect(() => {
    markerMapRef.current.forEach((marker, id) => {
      const el = marker.getElement()?.querySelector('.flag-marker');
      if (el) el.classList.toggle('active', id === activePlace);
    });
  }, [activePlace]);

  // ── Show / hide flag markers ──────────────────────────────────────────────
  useEffect(() => {
    if (!mapInstance) return;
    markerMapRef.current.forEach((marker) => {
      if (showFlags) marker.addTo(mapInstance);
      else marker.remove();
    });
  }, [showFlags, mapInstance]);

  // ── Load Leaflet ──────────────────────────────────────────────────────────
  useEffect(() => {
    loadStyle(LEAFLET_CSS);
    loadScript(LEAFLET_JS).then(() => setReady(true));
  }, []);

  // ── Init map ──────────────────────────────────────────────────────────────
  useEffect(() => {
    if (!ready || !mapElRef.current || mapRef.current) return;

    const L = window.L;

    const map = L.map(mapElRef.current, {
      center:            [20, 0],
      zoom:              2,
      zoomControl:       true,
      attributionControl: false,
    });

    const tile = L.tileLayer(OSM_URL, {
      attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',
      maxZoom: 19,
    }).addTo(map);
    tileLayerRef.current = tile;

    map.on('mousemove', (e) => {
      setCoords((prev) => ({ ...prev, lat: e.latlng.lat, lng: e.latlng.lng }));
    });

    map.on('zoomend', () => {
      setCoords((prev) => ({ ...prev, zoom: map.getZoom() }));
    });

    // Right-click → weather for any point
    map.on('contextmenu', (e) => {
      const { lat, lng } = e.latlng;
      const id = `custom-${lat.toFixed(4)}-${lng.toFixed(4)}`;
      setActivePlace(null);
      setWeatherPlace({ id, name: coordLabel(lat, lng), lat, lng });
      setShowRcHint(true);
      setTimeout(() => setShowRcHint(false), 3200);
    });

    // Flag markers for each place
    ALL_PLACES.forEach((place) => {
      const icon = L.divIcon({
        html:       `<div class="flag-marker">${place.flag}</div>`,
        className:  '',
        iconSize:   [28, 28],
        iconAnchor: [14, 14],
      });

      const marker = L.marker([place.lat, place.lng], { icon });
      marker.on('click', () => {
        map.flyTo([place.lat, place.lng], place.zoom, { duration: 1.2 });
        setActivePlace(place.id);
        setWeatherPlace({ id: place.id, name: `${place.flag} ${place.name}`, lat: place.lat, lng: place.lng });
        addRecent(place.id);
      });
      marker.addTo(map);
      markerMapRef.current.set(place.id, marker);
    });

    mapRef.current = map;
    setMapInstance(map);

    return () => {
      markerMapRef.current.clear();
      tileLayerRef.current = null;
      map.remove();
      mapRef.current = null;
      setMapInstance(null);
    };
  }, [ready]);

  // ── Derived state ─────────────────────────────────────────────────────────
  const activePlaceFull = useMemo(
    () => activePlace ? ALL_PLACES.find((p) => p.id === activePlace) ?? null : null,
    [activePlace],
  );

  const navEntries = useMemo(() => buildNavEntries(recent), [recent]);

  const zoomedEnoughForFlights = coords.zoom >= 5;
  const plugins = useMemo(() => getPlugins(), []);

  // ── Layer button definitions — non-plugin toggles first, then plugins ─────
  const layers: { icon: string; name: string; active: boolean; toggle: () => void; title: string; dividerAfter?: boolean }[] = [
    {
      icon: '🛰', name: 'Satellite', active: satellite,
      toggle: () => setSatellite((v) => !v), title: 'Satellite',
    },
    {
      icon: '🚩', name: 'Flags', active: showFlags,
      toggle: () => setShowFlags((v) => !v), title: 'Flags', dividerAfter: true,
    },
    ...plugins.map((plugin) => {
      const isEnabled = enabledLayers.has(plugin.id);
      const icon = plugin.label.split(' ')[0]; // emoji is first char
      const name = plugin.label.split(' ').slice(1).join(' ');
      const isFlightZoomWarning = plugin.id === 'flights' && isEnabled && !zoomedEnoughForFlights;
      return {
        icon,
        name: isFlightZoomWarning ? 'Zoom in' : (plugin.id === 'measure' && isEnabled ? 'Measuring…' : name),
        active: isEnabled,
        toggle: () => toggleLayer(plugin.id),
        title: isFlightZoomWarning ? 'Zoom in to see flights' : name,
      };
    }),
  ];

  const docControls = (
    <>
      <DocumentsMenu appId={EARTH_APP_ID} onLoad={handleLoad} />
      <IconBtn onClick={() => setShowSaveDialog(true)} data-tip="Save">
        <svg width={15} height={15} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
          <path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"/>
          <polyline points="17 21 17 13 7 13 7 21"/>
          <polyline points="7 3 7 8 15 8"/>
        </svg>
      </IconBtn>
    </>
  );

  const resetBtn = (
    <IconBtn onClick={handleReset} data-tip="World">
      <svg width={15} height={15} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
        <circle cx="12" cy="12" r="10" />
        <line x1="2" y1="12" x2="22" y2="12" />
        <path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z" />
      </svg>
    </IconBtn>
  );

  const sidebar = (
    <NavTree entries={navEntries} activeId={activePlace} onSelect={handleNavSelect} />
  );

  return (
    <>
    <Layout
      title="Earth"
      sidebar={sidebar}
      activeId={activePlace}
      topBarRight={<>
        {layers.map((l, i) => (
          <React.Fragment key={l.title}>
            <LayerBtn active={l.active} onClick={l.toggle} data-tip={l.title}>
              {l.icon}
            </LayerBtn>
            {l.dividerAfter && <LayerDivider />}
          </React.Fragment>
        ))}
        <LayerDivider />
        {resetBtn}
        {docControls}
        {topBarRight}
      </>}
    >
      <MapContainer>
        <MapArea>
          <MapWrapper satellite={satellite}>
            <div ref={mapElRef} style={{ height: '100%', width: '100%' }} />
          </MapWrapper>

          {plugins.map((plugin) => {
            const LayerComponent = plugin.component as unknown as React.ComponentType<Record<string, unknown>>;
            const extraProps = plugin.id === 'flights' ? { zoom: coords.zoom } : {};
            return (
              <LayerComponent
                key={plugin.id}
                map={mapInstance}
                enabled={enabledLayers.has(plugin.id)}
                {...extraProps}
              />
            );
          })}

          {showRcHint && (
            <RightClickHint>Right-click anywhere for instant weather</RightClickHint>
          )}

          <NotePanel visible={!!docNote}>
            <NotePanelHeader>
              <NotePanelTitle>Document note</NotePanelTitle>
              <NotePanelClose onClick={() => setDocNote(null)}>✕</NotePanelClose>
            </NotePanelHeader>
            <NotePanelBody>{docNote ?? ''}</NotePanelBody>
          </NotePanel>

          <WeatherPanel
            place={weatherPlace}
            onClose={handleWeatherClose}
          />
        </MapArea>

        <StatusBar>
          <span>Lat: {coords.lat.toFixed(4)}</span>
          <span>Lng: {coords.lng.toFixed(4)}</span>
          <span>Zoom: {coords.zoom}</span>
          <StatusSep>|</StatusSep>
          <span>UTC {formatUTC(now)}</span>
          {activePlaceFull && (
            <>
              <StatusSep>·</StatusSep>
              <span>
                {activePlaceFull.flag} {activePlaceFull.name}{' '}
                {formatLocalTime(now, activePlaceFull.timezone)}
              </span>
              <StatusSep>·</StatusSep>
              <span>{formatLocalDay(now, activePlaceFull.timezone)}</span>
            </>
          )}
          <span style={{ marginLeft: 'auto' }}>
            {satellite
              ? '© Esri, DigitalGlobe, GeoEye'
              : '© OpenStreetMap contributors'}
          </span>
        </StatusBar>
      </MapContainer>
    </Layout>

    {showSaveDialog && (
      <SaveDialog
        onSave={handleSave}
        onUpdate={handleUpdate}
        existingDoc={currentDoc ?? undefined}
        onCancel={() => setShowSaveDialog(false)}
      />
    )}
    </>
  );
}
